"""Emission compliance tests for tool_page (auto-generated by pact)."""

from tool_page.tool_page import ToolPage


class TestEmissionCompliance:
    """Verify tool_page emits structured events correctly."""

    def _make_handler(self):
        events = []
        return events, lambda event: events.append(event)

    def test_ToolPage_emits_events(self):
        """Method ToolPage emits invoked and completed events."""
        events, handler = self._make_handler()
        obj = ToolPage(event_handler=handler)
        try:
            obj.ToolPage()
        except (TypeError, Exception):
            pass
        invoked = [e for e in events if e.get("event") == "invoked"]
        completed = [e for e in events if e.get("event") in ("completed", "error")]
        assert len(invoked) >= 1, 'No invoked event for ToolPage'
        assert len(completed) >= 1, 'No completed/error event for ToolPage'
        assert invoked[0].get("pact_key") == "PACT:tool_page:ToolPage"
        assert isinstance(invoked[0].get("input_classification"), list)

