    def test_pact_key_format(self):
        """All emitted events have correctly formatted PACT keys."""
        events, handler = self._make_handler()
        obj = ToolPage(event_handler=handler)
        try:
            obj.ToolPage()
        except (TypeError, Exception):
            pass
        try:
            obj.CommentsSection()
        except (TypeError, Exception):
            pass
        try:
            obj.StepBadge()
        except (TypeError, Exception):
            pass
        try:
            obj.VersionBadge()
        except (TypeError, Exception):
            pass
        try:
            obj.CodeBlock()
        except (TypeError, Exception):
            pass
        try:
            obj.VideoEmbed()
        except (TypeError, Exception):
            pass
        try:
            obj.formatRelativeTime()
        except (TypeError, Exception):
            pass
        try:
            obj.isToolSlug()
        except (TypeError, Exception):
            pass
        try:
            obj.buildToolMap()
        except (TypeError, Exception):
            pass
        for event in events:
            key = event.get("pact_key", "")
            assert key.startswith("PACT:tool_page:"), f"Bad pact_key: {key}"

